/* ===== x12_guests.js ===== */
/* ============================================================================
   v5.5 LAYER 12 — Modules switch + wedding & guest-service options: guest list
   and household import, RSVP & meal counts with final catering approval,
   seating & table plans, invitations & guest messaging (consented), rooming &
   travel manifest, check-in & badges, couple/family collaboration with named
   rights, event website / guest information page.
   ========================================================================== */
coll('guests','households','tables','rooms','arrivals','familyLinks');
const MODULES=[['guests','Guest list, RSVP & meals','Households, per-function RSVP, dietary counts, final catering count'],['seating','Seating & table plans','Tables, constraints, printable plan'],['invitations','Invitations & guest messaging','Digital invite/RSVP links, templates, opt-out'],['rooming','Rooming & travel manifest','Rooms, arrivals, pickups, vehicle loads'],['checkin','Check-in & badges','Per-function check-in, QR, access zones'],['family','Family collaboration','Named decision rights, family link'],['website','Guest information page','Directions, schedule, dress code'],['inventory','Inventory & rentals','Own stock, allocation, damage/loss'],['dispatch','Equipment & vehicle dispatch','Packing lists, trips, handover'],['floorplans','Floor plans','Zones, layouts, versioned approvals'],['creative','Creative boards','Moodboards, proofs, version approvals'],['venueops','Venue / banquet operations','BEO, room blocks, minimum spend'],['registration','Delegates & registration','Public registration, ticket classes'],['ticketing','Ticketing, exhibitors, sponsors','Revenue lane with refunds'],['speakers','Speakers & sessions','Submissions, conflicts, stage cues'],['travel','Travel & insurance records','Bookings via providers, fees disclosed'],['ai','Assistants','Drafts with review: receipts, quotes, timelines, summaries'],['benchmark','Benchmarks','Private estimating; cross-company opt-in'],['marketplace','Sourcing network','Deferred; opt-in listing'],['fx','Multi-currency','Foreign-currency receipts, gains/losses']];
const modOn=k=>S.company.modules[k]!==false;
addPage('modules','Modules',vModules,()=>me().role==='owner');
function vModules(){return `${topbar()}<h1>Modules</h1><div class="small muted" style="margin:4px 0 10px">Everything is built; switch off what your company does not do and its tabs disappear for everyone. The core (events, money, vendors, tasks, crew, run sheet, documents) cannot be switched off. The sample company has every module on so you can see all of it.</div><div class="card"><div class="list">${MODULES.map(([k,l,d])=>`<div class="item"><div class="row between"><div><b>${esc(l)}</b><div class="meta">${esc(d)}</div></div><button class="btn sm ${modOn(k)?'pri':''}" data-act="mod-toggle" data-id="${k}">${modOn(k)?'On':'Off'}</button></div></div>`).join('')}</div></div>`}
act('mod-toggle',({id})=>{S.company.modules[id]=!modOn(id);S.company.modulesChosen=true;audit('update','modules',id,modOn(id)?'on':'off',null);save();render()});
/* ---------- Guests ---------- */
const guestsOf=eid=>live(S.guests).filter(g=>g.eventId===eid);
const hhOf=eid=>S.households.filter(h=>h.eventId===eid);
addTab('guests','Guests',tabGuests,(e,pre)=>!pre&&modOn('guests')&&(can('events.edit')||can('tasks.manage')||me().role==='staff'),'Work');
function rsvpCounts(e){const out={};fnNames(e).forEach(fn=>{const gs=guestsOf(e.id);const yes=gs.filter(g=>((g.rsvp||{}).perFunction||{})[fn]==='yes');out[fn]={invited:gs.filter(g=>!g.functions||!g.functions.length||g.functions.includes(fn)).length,yes:sum(yes,g=>(g.rsvp||{}).count||1),no:gs.filter(g=>((g.rsvp||{}).perFunction||{})[fn]==='no').length,pending:gs.filter(g=>!((g.rsvp||{}).perFunction||{})[fn]&&(!g.functions||!g.functions.length||g.functions.includes(fn))).length,dietary:{}};yes.forEach(g=>{(g.dietary||'').split(',').map(s=>s.trim()).filter(Boolean).forEach(d=>out[fn].dietary[d]=(out[fn].dietary[d]||0)+((g.rsvp||{}).count||1))})});return out}
function tabGuests(e,c){const gs=guestsOf(e.id);const hh=hhOf(e.id);const rc=rsvpCounts(e);const lk=locked(e);const edit=can('events.edit')&&!lk;const q=(S.ui.gq2||'').toLowerCase();const shown=gs.filter(g=>!q||(g.name+' '+(g.phone||'')+' '+(g.side||'')+' '+(hh.find(h=>h.id===g.householdId)||{}).name).toLowerCase().includes(q));const cc=e.cateringCount||{};
  return `<div class="card"><div class="row between"><div><h2>Guest list <span class="small muted">${gs.length} guests · ${hh.length} households</span></h2><div class="small muted">Only what the event needs: name, phone, household, side, function, RSVP, dietary. No addresses unless rooming needs them. Guests' consent to messages is recorded per household.</div></div>${edit?`<div class="row" style="gap:6px"><button class="btn sm" data-act="guest-import">Import CSV</button><button class="btn sm" data-act="household-add">+ Household</button><button class="btn sm pri" data-act="guest-add">+ Guest</button></div>`:''}</div>
  <div class="scroll" style="margin-top:8px"><table><thead><tr><th>Function</th><th class="r">Invited</th><th class="r">Yes (heads)</th><th class="r">No</th><th class="r">Pending</th><th>Dietary</th><th>Catering count</th></tr></thead><tbody>${fnNames(e).map(fn=>{const r=rc[fn];const f=cc[fn];const ph=agreedComms(e.id).find(cm=>cm.perHead&&(!(cm.functions||[]).length||cm.functions.includes(fn)));return `<tr><td><b>${esc(fn)}</b><div class="meta">${fnOf(e,fn).guests||0} planned</div></td><td class="r num">${r.invited}</td><td class="r num"><b>${r.yes}</b></td><td class="r num">${r.no}</td><td class="r num">${r.pending}</td><td class="small">${Object.entries(r.dietary).map(([k,v])=>`${esc(k)} ${v}`).join(' · ')||'—'}</td><td>${f?`<b>${f.count}</b> <span class="small muted">approved by ${esc(user(f.by).name)} ${fmtShort(f.at.slice(0,10))}</span>${ph&&ph.pricedFor!==f.count?` <span class="pill warn">${esc(vendor(ph.vendorId).name)} priced for ${ph.pricedFor}</span>`:''}`:'<span class="pill warn">not approved</span>'} ${edit?`<button class="btn sm" data-act="catering-count" data-v="${esc(fn)}">Set</button>`:''}</td></tr>`}).join('')}</tbody></table></div>
  <div class="row" style="gap:6px;margin:10px 0"><input id="gq2" data-act="gq2" value="${esc(S.ui.gq2||'')}" placeholder="Search guests" style="width:220px;padding:7px 10px;font-size:14px"><span class="small muted">${shown.length} shown</span></div>
  <div class="list">${shown.slice(0,150).map(g=>{const h=hh.find(x=>x.id===g.householdId);const r=g.rsvp||{};return `<div class="item" style="padding:6px 0"><div class="row between"><div><b>${esc(g.name)}</b> <span class="small muted">${h?'· '+esc(h.name):''}${g.side?' · '+esc(g.side):''}${g.phone?' · '+esc(g.phone):''}</span><div class="meta">${fnNames(e).map(fn=>{const s=(r.perFunction||{})[fn];return (!g.functions||!g.functions.length||g.functions.includes(fn))?`<span class="pill ${s==='yes'?'ok':s==='no'?'bad':'grey'}">${esc(fn)}: ${s||'?'}</span>`:''}).join(' ')}${r.count&&r.count>1?' · party of '+r.count:''}${g.dietary?' · '+esc(g.dietary):''}${g.access?' · '+esc(g.access):''}${g.table?' · table '+esc(g.table):''}${Object.keys(g.checkedIn||{}).length?' · checked in: '+Object.keys(g.checkedIn).join(', '):''}</div></div>${edit?`<div class="row" style="gap:4px"><button class="btn sm" data-act="guest-rsvp" data-id="${g.id}">RSVP</button><button class="btn sm" data-act="guest-edit" data-id="${g.id}">Edit</button></div>`:''}</div></div>`}).join('')||'<div class="muted" style="padding:10px 0">No guests. Import a CSV (name, phone, household, side) or add by hand. Whether the planner owns the guest list at all is the client\'s call — many families keep it themselves.</div>'}</div>
  ${modOn('invitations')?invitationsCard(e):''}${modOn('seating')?seatingCard(e):''}${modOn('rooming')?roomingCard(e):''}${modOn('checkin')?checkinCard(e):''}${modOn('family')?familyCard(e):''}${modOn('website')?websiteCard(e):''}</div>`}
ACTS_INPUT['gq2']=el=>{S.ui.gq2=el.value;saveUI();const pos=el.selectionStart;render();const n=F('gq2');if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}};
act('household-add',({E})=>{const e=E();openModal(`${hd('Household')}<form id="f-hh"><label for="hhn">Name (e.g. "Menon, Panampilly Nagar")</label><input id="hhn" required><label for="hhp">Contact phone</label><input id="hhp" inputmode="tel"><label for="hhs">Side</label><select id="hhs"><option>Bride</option><option>Groom</option><option>Both / friends</option><option>Vendor / VIP</option></select><label class="chk"><input type="checkbox" id="hhc"> This household agreed to receive event messages on this number</label>${ft('Add')}</form>`);F('f-hh').addEventListener('submit',x=>{x.preventDefault();S.households.push({id:uid(),eventId:e.id,name:F('hhn').value.trim(),phone:F('hhp').value.trim(),side:F('hhs').value,consent:F('hhc').checked?{messages:true,at:nowISO(),by:UI.userId}:null,token:Math.random().toString(36).slice(2,10)});save();closeModal();render()})});
act('guest-add',({E,id})=>mGuest(E(),id?S.guests.find(g=>g.id===id):null));act('guest-edit',({E,id})=>mGuest(E(),S.guests.find(g=>g.id===id)));
function mGuest(e,g){const isNew=!g;g=g||{name:'',phone:'',householdId:'',side:'',functions:[],dietary:'',access:'',notes:''};openModal(`${hd(isNew?'Add guest':'Edit guest')}<form id="f-g"><label for="gn">Name</label><input id="gn" required value="${esc(g.name)}"><div class="two"><div><label for="gp">Phone (optional)</label><input id="gp" inputmode="tel" value="${esc(g.phone||'')}"></div><div><label for="gh">Household</label><select id="gh"><option value="">—</option>${hhOf(e.id).map(h=>`<option value="${h.id}" ${g.householdId===h.id?'selected':''}>${esc(h.name)}</option>`).join('')}</select></div></div><label>Invited to</label><div class="chips">${fnNames(e).map(fn=>`<label class="btn chip sm" style="margin:0"><input type="checkbox" class="gfn" value="${esc(fn)}" ${!g.functions||!g.functions.length||g.functions.includes(fn)?'checked':''} style="margin-right:4px">${esc(fn)}</label>`).join('')}</div><div class="two"><div><label for="gd">Dietary (comma separated)</label><input id="gd" value="${esc(g.dietary||'')}" placeholder="vegetarian, no nuts"></div><div><label for="ga">Access / assistance</label><input id="ga" value="${esc(g.access||'')}" placeholder="wheelchair, elderly"></div></div><div class="help">Dietary and access notes are sensitive: shown only to the planner, caterer counts and the guest desk, never on public pages.</div>${ft('Save')}</form>`);F('f-g').addEventListener('submit',x=>{x.preventDefault();const d={name:F('gn').value.trim(),phone:F('gp').value.trim(),householdId:F('gh').value||null,functions:[...document.querySelectorAll('.gfn:checked')].map(c=>c.value),dietary:F('gd').value.trim(),access:F('ga').value.trim()};if(!d.name)return;if(isNew){if(guestsOf(e.id).some(x=>x.name.toLowerCase()===d.name.toLowerCase()&&(x.phone||'')===(d.phone||'')))return toast('Already on the list');S.guests.push(stamp(Object.assign({id:uid(),eventId:e.id,rsvp:{perFunction:{},count:1},checkedIn:{}},d)))}else{Object.assign(g,d);touch(g)}save();closeModal();render()})}
act('guest-rsvp',({E,id})=>{const e=E();const g=S.guests.find(x=>x.id===id);const r=g.rsvp||{perFunction:{},count:1};openModal(`${hd('RSVP: '+esc(g.name))}<form id="f-rv">${fnNames(e).filter(fn=>!g.functions||!g.functions.length||g.functions.includes(fn)).map(fn=>`<label for="rv_${esc(fn)}">${esc(fn)}</label><select id="rv_${esc(fn)}" data-fn="${esc(fn)}" class="rvf"><option value="">No answer</option><option value="yes" ${(r.perFunction||{})[fn]==='yes'?'selected':''}>Yes</option><option value="no" ${(r.perFunction||{})[fn]==='no'?'selected':''}>No</option></select>`).join('')}<label for="rvc">Heads attending (incl. this guest)</label><input id="rvc" inputmode="numeric" value="${r.count||1}"><label for="rvb">Answered by / how</label><input id="rvb" value="${esc(r.by||'')}" placeholder="Phone call with Meera / RSVP link">${ft('Save')}</form>`);F('f-rv').addEventListener('submit',x=>{x.preventDefault();const pf={};document.querySelectorAll('.rvf').forEach(s=>{if(s.value)pf[s.dataset.fn]=s.value});g.rsvp={perFunction:pf,count:Math.max(1,parseInt(F('rvc').value)||1),by:F('rvb').value.trim(),at:nowISO()};touch(g);save();closeModal();render()})});
act('catering-count',({E,v})=>{const e=E();const rc=rsvpCounts(e)[v];openModal(`${hd('Final catering count: '+esc(v))}<form id="f-cc3"><p class="small">RSVP yes: <b>${rc.yes}</b> heads · pending ${rc.pending} · planned ${fnOf(e,v).guests||0}. Caterers usually want the number 48–72 hours before; whether yours does is <b>unknown</b> — check the agreement.</p><label for="ccn">Count to give the caterer</label><input id="ccn" class="big" inputmode="numeric" value="${(e.cateringCount||{})[v]?e.cateringCount[v].count:rc.yes}"><label for="ccb">Buffer reason (if above RSVP)</label><input id="ccb" placeholder="+5% for walk-ins per family">${ft('Approve count')}</form>`);F('f-cc3').addEventListener('submit',x=>{x.preventDefault();e.cateringCount=e.cateringCount||{};e.cateringCount[v]={count:parseInt(F('ccn').value)||0,by:UI.userId,at:nowISO(),note:F('ccb').value.trim(),rsvpYes:rc.yes};touch(e);audit('update','events',e.id,'catering count '+v+' '+e.cateringCount[v].count,e.id);const ph=agreedComms(e.id).filter(cm=>cm.perHead&&(!(cm.functions||[]).length||cm.functions.includes(v)));ph.forEach(cm=>{if(cm.pricedFor!==e.cateringCount[v].count)notify(e.plannerId,`${vendor(cm.vendorId).name} is priced for ${cm.pricedFor}; final count for ${v} is ${e.cateringCount[v].count} — re-price or confirm`,e.id)});save();closeModal();render()})});
ACTS_FILE['guest-csv']=input=>{const f=input.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{const rows=csvRows(r.result);const e=ev(S.ui.eventId);let n=0,dup=0,bad=0;rows.forEach(row=>{const name=(row.name||row.Name||'').trim();if(!name){bad++;return}const phone=(row.phone||row.Phone||'').trim();if(guestsOf(e.id).some(g=>g.name.toLowerCase()===name.toLowerCase()&&(g.phone||'')===phone)){dup++;return}const hhName=(row.household||row.Household||'').trim();let hh=hhName?hhOf(e.id).find(h=>h.name.toLowerCase()===hhName.toLowerCase()):null;if(hhName&&!hh){hh={id:uid(),eventId:e.id,name:hhName,phone:'',side:(row.side||row.Side||'').trim(),consent:null,token:Math.random().toString(36).slice(2,10)};S.households.push(hh)}S.guests.push(stamp({id:uid(),eventId:e.id,name,phone,householdId:hh?hh.id:null,side:(row.side||row.Side||'').trim(),functions:[],dietary:(row.dietary||row.Dietary||'').trim(),access:'',rsvp:{perFunction:{},count:1},checkedIn:{}}));n++});audit('create','guests',e.id,n+' imported',e.id);save();closeModal();render();toast(`${n} guests added, ${dup} duplicates skipped, ${bad} rows without a name`)};r.readAsText(f)};
act('guest-import',()=>openModal(`${hd('Import guests')}<p class="small">CSV with columns <b>name, phone, household, side, dietary</b> (any order; first row headings). Duplicates by name + phone are skipped; households are created as needed. Keep the file minimal — no addresses, no IDs.</p><input type="file" accept=".csv,text/csv" data-file="guest-csv"><div class="ft"><button class="btn" data-act="close">Close</button></div>`));
/* ---------- Invitations & guest messaging ---------- */
function invitationsCard(e){const hh=hhOf(e.id);const sent=hh.filter(h=>h.inviteSentAt).length;const opted=hh.filter(h=>h.optOut).length;const consent=hh.filter(h=>h.consent).length;return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Invitations & RSVP links</h3><div class="small muted">One link per household; it shows the invite and collects RSVPs per function. Sent only to households that agreed to messages; opt-out stops everything. Nothing is bulk-sent from here. ${sb('WhatsApp template delivery')}</div></div><button class="btn sm" data-act="invite-template">Template</button></div><div class="grid g3" style="margin-top:8px">${stat('Households',hh.length,`${consent} consented · ${opted} opted out`)}${stat('Links prepared',sent,'')}${stat('RSVPs in',hh.filter(h=>guestsOf(e.id).some(g=>g.householdId===h.id&&Object.keys((g.rsvp||{}).perFunction||{}).length)).length,'households with an answer')}</div><div class="list" style="margin-top:6px">${hh.map(h=>`<div class="item" style="padding:5px 0"><div class="row between"><div class="small"><b>${esc(h.name)}</b> · ${esc(h.phone||'no phone')} · ${esc(h.side||'')} ${h.consent?'<span class="pill ok">consented</span>':'<span class="pill warn">no consent</span>'}${h.optOut?' <span class="pill bad">opted out</span>':''}${h.inviteSentAt?' · link prepared '+fmtShort(h.inviteSentAt.slice(0,10)):''}${h.rsvpAt?' · answered '+fmtShort(h.rsvpAt.slice(0,10)):''}</div><div class="row" style="gap:4px">${h.consent&&!h.optOut?`<button class="btn sm" data-act="invite-send" data-id="${h.id}">Invite text</button>`:''}<a class="btn sm" href="#rsvp/${h.token}" style="text-decoration:none">Open RSVP page</a><button class="btn sm" data-act="hh-optout" data-id="${h.id}">${h.optOut?'Undo opt-out':'Opt out'}</button></div></div></div>`).join('')||'<div class="muted small">No households.</div>'}</div></div>`}
act('invite-template',({E})=>{const e=E();openModal(`${hd('Invitation template')}<form id="f-it"><textarea id="itt" style="min-height:140px">${esc(e.inviteTemplate||`Dear {{household}},\n\nWith great joy we invite you to {{event}} on {{date}} at {{venue}}.\nPlease tell us who is coming: {{link}}\n\nWarmly,\n{{client}}`)}</textarea><div class="help">Placeholders: {{household}} {{event}} {{date}} {{venue}} {{link}} {{client}}</div>${ft('Save')}</form>`);F('f-it').addEventListener('submit',x=>{x.preventDefault();e.inviteTemplate=F('itt').value;touch(e);save();closeModal();render()})});
act('invite-send',({E,id})=>{const e=E();const h=S.households.find(x=>x.id===id);const t=(e.inviteTemplate||`Dear {{household}},\n\nWith great joy we invite you to {{event}} on {{date}} at {{venue}}.\nPlease tell us who is coming: {{link}}\n\nWarmly,\n{{client}}`).replace(/\{\{household\}\}/g,h.name).replace(/\{\{event\}\}/g,e.name).replace(/\{\{date\}\}/g,fmtDate(e.startDate)).replace(/\{\{venue\}\}/g,e.venue||'').replace(/\{\{link\}\}/g,location.href.split('#')[0]+'#rsvp/'+h.token).replace(/\{\{client\}\}/g,e.client);h.inviteSentAt=nowISO();h.inviteBy=UI.userId;save();render();mCopy('Invitation for '+h.name,t)});
act('hh-optout',({id})=>{const h=S.households.find(x=>x.id===id);h.optOut=!h.optOut;h.optOutAt=h.optOut?nowISO():null;save();render()});
PAGES_EXT.rsvp=()=>vRsvp();PAGES_EXT.family=()=>vFamily();PAGES_EXT.guestinfo=()=>vGuestInfo();PAGES_EXT.register=()=>vRegister();
function vRsvp(){const tok=S.ui.rsvpToken||'';const h=S.households.find(x=>x.token===tok);const back=`<a href="#events" class="btn sm" style="text-decoration:none;margin-top:10px;display:inline-block">← Back to the app</a>`;if(!h)return `<div class="login"><div class="card" style="max-width:520px;margin:30px auto"><h2>Link not found</h2>${back}</div></div>`;const e=ev(h.eventId);const gs=guestsOf(e.id).filter(g=>g.householdId===h.id);return `<div class="login"><div class="card" style="max-width:560px;margin:30px auto"><div class="eyebrow">${esc(e.client)} · invitation</div><h1 style="font-size:22px">${esc(e.name)}</h1><div class="small muted">${fmtDate(e.startDate)}${e.endDate?' – '+fmtDate(e.endDate):''} · ${esc(e.venue||'')}</div><p class="small">Dear ${esc(h.name)}, please tell us who is coming to each function.</p><form id="f-rsvp"><div class="scroll"><table><thead><tr><th>Guest</th>${fnNames(e).map(f=>`<th>${esc(f)}</th>`).join('')}</tr></thead><tbody>${gs.map(g=>`<tr><td>${esc(g.name)}</td>${fnNames(e).map(f=>`<td><select class="rvp" data-g="${g.id}" data-fn="${esc(f)}" style="padding:4px"><option value="">—</option><option value="yes" ${((g.rsvp||{}).perFunction||{})[f]==='yes'?'selected':''}>Yes</option><option value="no" ${((g.rsvp||{}).perFunction||{})[f]==='no'?'selected':''}>No</option></select></td>`).join('')}</tr>`).join('')}</tbody></table></div><label for="rvd">Dietary needs for your family (optional)</label><input id="rvd" value="${esc(gs.map(g=>g.dietary).filter(Boolean).join(', '))}"><label for="rvn">Your name</label><input id="rvn" required><div class="ft"><button class="btn" type="button" data-act="rsvp-optout">Please stop messaging us</button><button class="btn pri" type="submit">Send RSVP</button></div></form><div class="meta" style="margin-top:10px">${esc(S.company.name)} manages this event for ${esc(e.client)}. Your answers go to them only. ${sb('public RSVP link')}</div>${back}</div></div>`}
document.addEventListener('submit',evt=>{if(evt.target.id!=='f-rsvp')return;evt.preventDefault();const h=S.households.find(x=>x.token===S.ui.rsvpToken);const by=F('rvn').value.trim();document.querySelectorAll('.rvp').forEach(s=>{const g=S.guests.find(x=>x.id===s.dataset.g);g.rsvp=g.rsvp||{perFunction:{},count:1};if(s.value)g.rsvp.perFunction[s.dataset.fn]=s.value;else delete g.rsvp.perFunction[s.dataset.fn];g.rsvp.by=by+' (RSVP link)';g.rsvp.at=nowISO();if(F('rvd').value.trim())g.dietary=F('rvd').value.trim()});h.rsvpAt=nowISO();const e=ev(h.eventId);S.notes.push({id:uid(),userId:e.plannerId,text:`RSVP from ${h.name} (${by})`,ts:nowISO(),read:false,eventId:e.id});save();render();toast('Thank you — recorded')});
act('rsvp-optout',()=>{const h=S.households.find(x=>x.token===S.ui.rsvpToken);h.optOut=true;h.optOutAt=nowISO();save();render();toast('You will not be messaged again')});
BOOT_EXT.push(()=>{const re=[[/^#rsvp\/(\w+)/,'rsvpToken','rsvp'],[/^#family\/(\w+)/,'familyToken','family'],[/^#guestinfo\/(\w+)/,'guestinfoToken','guestinfo'],[/^#register\/(\w+)/,'registerToken','register']];const apply=()=>{re.forEach(([rx,k,page])=>{const m=location.hash.match(rx);if(m){S.ui[k]=m[1];saveUI();if(location.hash!=='#'+page)location.hash=page}})};apply();window.addEventListener('hashchange',apply)});
const _renderGate6=render;render=function(){const r=route();const h=location.hash;const pub={rsvp:()=>vRsvp(),family:()=>vFamily(),guestinfo:()=>vGuestInfo(),register:()=>vRegister()};const k=Object.keys(pub).find(x=>r===x||h.startsWith('#'+x+'/'));if(k){bindUI();document.getElementById('nav').innerHTML='';document.getElementById('tabbar').innerHTML='';document.getElementById('sidefoot').innerHTML='';document.getElementById('app').innerHTML=pub[k]();return}return _renderGate6()};
/* ---------- Seating ---------- */
function seatingCard(e){const fn=S.ui.seatFn&&fnNames(e).includes(S.ui.seatFn)?S.ui.seatFn:fnNames(e)[0];const ts=S.tables.filter(t=>t.eventId===e.id&&t.fn===fn);const gs=guestsOf(e.id).filter(g=>((g.rsvp||{}).perFunction||{})[fn]==='yes');const seated=gs.filter(g=>(g.table||{})[fn]);const cap=sum(ts,t=>t.capacity);const problems=[];ts.forEach(t=>{const at=gs.filter(g=>(g.table||{})[fn]===t.id);const heads=sum(at,g=>(g.rsvp||{}).count||1);if(heads>t.capacity)problems.push(`${t.name}: ${heads} heads for ${t.capacity} seats`);at.forEach(g=>(g.apart||[]).forEach(id=>{if(at.some(x=>x.id===id))problems.push(`${g.name} and ${(S.guests.find(x=>x.id===id)||{}).name} must be apart (${t.name})`)}))});gs.forEach(g=>(g.together||[]).forEach(id=>{const o=S.guests.find(x=>x.id===id);if(o&&(g.table||{})[fn]&&(o.table||{})[fn]&&(g.table||{})[fn]!==(o.table||{})[fn])problems.push(`${g.name} and ${o.name} should sit together`)}));const venueChanged=e.seatingVenue&&e.seatingVenue[fn]&&e.seatingVenue[fn]!==fnOf(e,fn).venue;
  return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Seating · ${esc(fn)}</h3><div class="small muted">${ts.length} tables · ${cap} seats · ${seated.length}/${gs.length} confirmed guests seated. Constraints (together / apart) are checked, not enforced. ${venueChanged?'<span class="pill bad">venue changed since this plan was made</span>':''}</div></div><div class="row" style="gap:6px"><select data-act="seat-fn" style="width:auto;padding:6px 10px;font-size:13px">${fnNames(e).map(f=>`<option ${f===fn?'selected':''}>${esc(f)}</option>`).join('')}</select>${can('events.edit')&&!locked(e)?`<button class="btn sm" data-act="table-add" data-v="${esc(fn)}">+ Table</button><button class="btn sm" data-act="seat-auto" data-v="${esc(fn)}">Auto-seat by household</button>`:''}<button class="btn sm" data-act="seat-print" data-v="${esc(fn)}">Print plan</button></div></div>${problems.length?`<div class="alert" style="margin-top:6px">${problems.map(esc).join('<br>')}</div>`:''}<div class="plan" style="margin-top:8px;height:${Math.max(200,Math.ceil(ts.length/6)*90+40)}px">${ts.map((t,i)=>{const at=gs.filter(g=>(g.table||{})[fn]===t.id);const heads=sum(at,g=>(g.rsvp||{}).count||1);return `<div class="tbl ${t.shape==='rect'?'sq':''}" style="left:${t.x!=null?t.x:20+(i%6)*95}px;top:${t.y!=null?t.y:20+Math.floor(i/6)*90}px;border-color:${heads>t.capacity?'var(--bad)':'var(--gold)'}" title="${esc(t.name)}: ${heads}/${t.capacity}" data-act="table-open" data-id="${t.id}">${esc(t.name)}<br><span class="small">${heads}/${t.capacity}</span></div>`}).join('')}</div><div class="meta" style="margin-top:4px">Tap a table to seat guests. Unseated confirmed: ${gs.filter(g=>!(g.table||{})[fn]).slice(0,8).map(g=>esc(g.name)).join(', ')}${gs.filter(g=>!(g.table||{})[fn]).length>8?'…':''}</div></div>`}
ACTS_CHANGE['seat-fn']=el=>{S.ui.seatFn=el.value;saveUI();render()};
act('table-add',({E,v})=>{const e=E();openModal(`${hd('Add tables')}<form id="f-tb"><div class="grid g3" style="gap:8px"><div><label for="tbn">How many</label><input id="tbn" inputmode="numeric" value="10"></div><div><label for="tbc">Seats each</label><input id="tbc" inputmode="numeric" value="10"></div><div><label for="tbs">Shape</label><select id="tbs"><option value="round">Round</option><option value="rect">Rectangular</option></select></div></div><label for="tbz">Zone / prefix</label><input id="tbz" value="T">${ft('Add')}</form>`);F('f-tb').addEventListener('submit',x=>{x.preventDefault();const n=parseInt(F('tbn').value)||1,c=parseInt(F('tbc').value)||8;const start=S.tables.filter(t=>t.eventId===e.id&&t.fn===v).length;for(let i=0;i<n;i++)S.tables.push({id:uid(),eventId:e.id,fn:v,name:F('tbz').value+(start+i+1),capacity:c,shape:F('tbs').value,x:null,y:null});e.seatingVenue=Object.assign(e.seatingVenue||{},{[v]:fnOf(e,v).venue});save();closeModal();render()})});
act('table-open',({E,id})=>{const e=E();const t=S.tables.find(x=>x.id===id);const gs=guestsOf(e.id).filter(g=>((g.rsvp||{}).perFunction||{})[t.fn]==='yes');openModal(`${hd(esc(t.name)+' · '+t.capacity+' seats')}<form id="f-seat"><div class="list" style="max-height:40vh;overflow:auto">${gs.map(g=>`<label class="chk item" style="margin:0"><input type="checkbox" class="sg" value="${g.id}" ${(g.table||{})[t.fn]===t.id?'checked':''} ${(g.table||{})[t.fn]&&(g.table||{})[t.fn]!==t.id?'disabled':''}> ${esc(g.name)} <span class="small muted">${(g.rsvp||{}).count>1?'×'+(g.rsvp||{}).count:''}${(g.table||{})[t.fn]&&(g.table||{})[t.fn]!==t.id?' · at '+esc((S.tables.find(x=>x.id===(g.table||{})[t.fn])||{}).name):''}${g.access?' · '+esc(g.access):''}</span></label>`).join('')}</div><div class="two"><div><label for="stn">Rename</label><input id="stn" value="${esc(t.name)}"></div><div><label for="stc">Seats</label><input id="stc" inputmode="numeric" value="${t.capacity}"></div></div><div class="ft"><button class="btn" data-act="close">Cancel</button><button class="btn" type="button" data-act="table-del" data-id="${t.id}">Remove table</button><button class="btn pri" type="submit">Save</button></div></form>`);F('f-seat').addEventListener('submit',x=>{x.preventDefault();document.querySelectorAll('.sg').forEach(c=>{const g=S.guests.find(y=>y.id===c.value);g.table=g.table||{};if(c.checked)g.table[t.fn]=t.id;else if(g.table[t.fn]===t.id)delete g.table[t.fn]});t.name=F('stn').value.trim()||t.name;t.capacity=parseInt(F('stc').value)||t.capacity;save();closeModal();render()})});
act('table-del',({id})=>{const t=S.tables.find(x=>x.id===id);S.guests.forEach(g=>{if(g.table&&g.table[t.fn]===id)delete g.table[t.fn]});S.tables=S.tables.filter(x=>x.id!==id);save();closeModal();render()});
act('seat-auto',({E,v})=>{const e=E();const ts=S.tables.filter(t=>t.eventId===e.id&&t.fn===v);if(!ts.length)return toast('Add tables first');const gs=guestsOf(e.id).filter(g=>((g.rsvp||{}).perFunction||{})[v]==='yes'&&!(g.table||{})[v]);const byHh={};gs.forEach(g=>{(byHh[g.householdId||g.id]=byHh[g.householdId||g.id]||[]).push(g)});const load=t=>sum(guestsOf(e.id).filter(g=>(g.table||{})[v]===t.id),g=>(g.rsvp||{}).count||1);let placed=0;Object.values(byHh).sort((a,b)=>b.length-a.length).forEach(group=>{const heads=sum(group,g=>(g.rsvp||{}).count||1);const t=ts.find(t=>t.capacity-load(t)>=heads)||ts.sort((a,b)=>(b.capacity-load(b))-(a.capacity-load(a)))[0];group.forEach(g=>{g.table=g.table||{};g.table[v]=t.id;placed++})});save();render();toast(placed+' guests seated by household; check the warnings')});
act('seat-print',({E,v})=>{const e=E();const ts=S.tables.filter(t=>t.eventId===e.id&&t.fn===v);const lines=[];ts.forEach(t=>{const at=guestsOf(e.id).filter(g=>(g.table||{})[v]===t.id);lines.push({t:`${t.name} (${t.capacity}): ${at.map(g=>g.name+((g.rsvp||{}).count>1?' x'+(g.rsvp||{}).count:'')).join(', ')||'—'}`})});downloadBlob('seating-'+v+'.pdf',makePdf(`Seating plan — ${e.name} — ${v}`,lines))});
/* ---------- Rooming & travel ---------- */
function roomingCard(e){const rooms=S.rooms.filter(r=>r.eventId===e.id);const arr=S.arrivals.filter(a=>a.eventId===e.id).sort((a,b)=>(a.at||'').localeCompare(b.at||''));const vehicles=(S.vehicles||[]);return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Rooming & travel</h3><div class="small muted">Only if the planner actually coordinates stays and pickups. Rooms, arrivals, pickups with vehicle capacity, and a guest-facing itinerary text.</div></div>${can('events.edit')&&!locked(e)?`<div class="row" style="gap:6px"><button class="btn sm" data-act="room-add">+ Room</button><button class="btn sm" data-act="arrival-add">+ Arrival</button><button class="btn sm" data-act="manifest-copy">Manifest text</button></div>`:''}</div><div class="grid g2" style="margin-top:6px"><div><div class="eyebrow">Rooms (${rooms.length})</div><div class="list">${rooms.map(r=>`<div class="item small" style="padding:4px 0"><b>${esc(r.hotel)} ${esc(r.room)}</b> · ${fmtShort(r.checkIn)}–${fmtShort(r.checkOut)} · ${r.guestIds.map(id=>esc((S.guests.find(g=>g.id===id)||{name:'?'}).name)).join(', ')||'<span class="muted">unassigned</span>'} ${r.guestIds.length>r.capacity?'<span class="pill bad">over capacity</span>':''} <button class="btn sm" data-act="room-del" data-id="${r.id}">×</button></div>`).join('')||'<div class="muted small">None.</div>'}</div></div><div><div class="eyebrow">Arrivals & pickups (${arr.length})</div><div class="list">${arr.map(a=>{const v=vehicles.find(x=>x.id===a.vehicleId);const loadN=S.arrivals.filter(x=>x.vehicleId===a.vehicleId&&x.at===a.at&&x.eventId===e.id).reduce((t,x)=>t+(x.pax||1),0);return `<div class="item small" style="padding:4px 0"><b>${esc((S.guests.find(g=>g.id===a.guestId)||{name:a.name||'?'}).name)}</b> · ${esc(a.mode)} ${esc(a.ref||'')} · ${esc(a.at||'')} · ${a.pax||1} pax ${a.pickup?`· pickup ${v?esc(v.name):'(no vehicle)'}${v&&loadN>v.capacity?' <span class="pill bad">over capacity '+loadN+'/'+v.capacity+'</span>':''}`:''} <button class="btn sm" data-act="arrival-del" data-id="${a.id}">×</button></div>`}).join('')||'<div class="muted small">None.</div>'}</div></div></div></div>`}
act('room-add',({E})=>{const e=E();openModal(`${hd('Room')}<form id="f-rm"><div class="two"><div><label for="rmh">Hotel</label><input id="rmh" required></div><div><label for="rmr">Room</label><input id="rmr" required></div></div><div class="grid g3" style="gap:8px"><div><label for="rmi">Check-in</label><input id="rmi" type="date" value="${addDays(e.startDate,-1)}"></div><div><label for="rmo">Check-out</label><input id="rmo" type="date" value="${addDays(e.endDate||e.startDate,1)}"></div><div><label for="rmc">Capacity</label><input id="rmc" inputmode="numeric" value="2"></div></div><label>Guests</label><div class="list" style="max-height:30vh;overflow:auto">${guestsOf(e.id).slice(0,200).map(g=>`<label class="chk item" style="margin:0"><input type="checkbox" class="rmg" value="${g.id}"> ${esc(g.name)}</label>`).join('')}</div>${ft('Save')}</form>`);F('f-rm').addEventListener('submit',x=>{x.preventDefault();S.rooms.push({id:uid(),eventId:e.id,hotel:F('rmh').value.trim(),room:F('rmr').value.trim(),checkIn:F('rmi').value,checkOut:F('rmo').value,capacity:parseInt(F('rmc').value)||2,guestIds:[...document.querySelectorAll('.rmg:checked')].map(c=>c.value)});save();closeModal();render()})});
act('room-del',({id})=>{S.rooms=S.rooms.filter(r=>r.id!==id);save();render()});
act('arrival-add',({E})=>{const e=E();openModal(`${hd('Arrival')}<form id="f-ar"><label for="arg">Guest</label><select id="arg"><option value="">(not on guest list)</option>${guestsOf(e.id).map(g=>`<option value="${g.id}">${esc(g.name)}</option>`).join('')}</select><input id="arn" placeholder="Name if not on list"><div class="grid g3" style="gap:8px"><div><label for="arm">Mode</label><select id="arm"><option>flight</option><option>train</option><option>car</option></select></div><div><label for="arr">Ref (flight/train no)</label><input id="arr"></div><div><label for="art">Arrives</label><input id="art" type="datetime-local" value="${addDays(e.startDate,-1)}T10:00"></div></div><div class="two"><div><label for="arp">Pax</label><input id="arp" inputmode="numeric" value="1"></div><div><label for="arv">Pickup vehicle</label><select id="arv"><option value="">No pickup</option>${(S.vehicles||[]).map(v=>`<option value="${v.id}">${esc(v.name)} (${v.capacity})</option>`).join('')}</select></div></div>${ft('Save')}</form>`);F('f-ar').addEventListener('submit',x=>{x.preventDefault();S.arrivals.push({id:uid(),eventId:e.id,guestId:F('arg').value||null,name:F('arn').value.trim(),mode:F('arm').value,ref:F('arr').value.trim(),at:F('art').value,pax:parseInt(F('arp').value)||1,pickup:!!F('arv').value,vehicleId:F('arv').value||null});save();closeModal();render()})});
act('arrival-del',({id})=>{S.arrivals=S.arrivals.filter(a=>a.id!==id);save();render()});
act('manifest-copy',({E})=>{const e=E();const arr=S.arrivals.filter(a=>a.eventId===e.id).sort((a,b)=>(a.at||'').localeCompare(b.at||''));const rooms=S.rooms.filter(r=>r.eventId===e.id);mCopy('Travel & rooming manifest',`${e.name} — arrivals\n`+arr.map(a=>`${(a.at||'').replace('T',' ')}  ${(S.guests.find(g=>g.id===a.guestId)||{name:a.name}).name} · ${a.mode} ${a.ref||''} · ${a.pax} pax${a.pickup?' · pickup '+((S.vehicles||[]).find(v=>v.id===a.vehicleId)||{name:'?'}).name:''}`).join('\n')+`\n\nRooms\n`+rooms.map(r=>`${r.hotel} ${r.room}: ${r.guestIds.map(id=>(S.guests.find(g=>g.id===id)||{name:'?'}).name).join(', ')} (${fmtShort(r.checkIn)}–${fmtShort(r.checkOut)})`).join('\n'),'For the transport team and hotel desk. Guest-facing itineraries go out per household from the RSVP page.')});
/* ---------- Check-in & badges ---------- */
function qrSvg(seed){let h=0;for(const c of seed)h=(h*31+c.charCodeAt(0))>>>0;let cells='';for(let i=0;i<441;i++){h=(h*1103515245+12345)>>>0;const on=(h>>16)&1;const r=Math.floor(i/21),c=i%21;const finder=(r<7&&c<7)||(r<7&&c>13)||(r>13&&c<7);cells+=`<i style="background:${finder?((r===0||r===6||c===0||c===6||c===14||c===20||r===14||r===20)||(r>=2&&r<=4&&(c>=2&&c<=4||c>=16&&c<=18))||(r>=16&&r<=18&&c>=2&&c<=4)?'var(--ink)':'transparent'):on?'var(--ink)':'transparent'}"></i>`}return `<div class="qr">${cells}</div>`}
function checkinCard(e){const fn=S.ui.ciFn&&fnNames(e).includes(S.ui.ciFn)?S.ui.ciFn:fnNames(e).find(f=>isFnDay(e,f))||fnNames(e)[0];const gs=guestsOf(e.id).filter(g=>((g.rsvp||{}).perFunction||{})[fn]==='yes');const inn=gs.filter(g=>(g.checkedIn||{})[fn]);const q=(S.ui.ciq||'').toLowerCase();const found=q?gs.filter(g=>g.name.toLowerCase().includes(q)||(g.phone||'').includes(q)).slice(0,8):[];const zones=e.accessZones||['Main'];return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Check-in · ${esc(fn)} <span class="pill ${inn.length===gs.length&&gs.length?'ok':'grey'}">${inn.length}/${gs.length}</span></h3><div class="small muted">Search or scan; a guest cannot be checked in twice for the same function. Works offline on this device. Zones: ${zones.map(esc).join(', ')}</div></div><div class="row" style="gap:6px"><select data-act="ci-fn" style="width:auto;padding:6px 10px;font-size:13px">${fnNames(e).map(f=>`<option ${f===fn?'selected':''}>${esc(f)}</option>`).join('')}</select><button class="btn sm" data-act="zones-edit">Zones</button><button class="btn sm" data-act="badges-print" data-v="${esc(fn)}">Badges PDF</button></div></div><input id="ciq" data-act="ciq" value="${esc(S.ui.ciq||'')}" placeholder="Type a name or phone (or scan)" style="margin:8px 0;max-width:360px">${found.length?`<div class="list">${found.map(g=>{const done=(g.checkedIn||{})[fn];return `<div class="item" style="padding:6px 0"><div class="row between"><div><b>${esc(g.name)}</b> <span class="small muted">· ${(g.rsvp||{}).count||1} pax${g.table&&g.table[fn]?' · '+esc((S.tables.find(t=>t.id===g.table[fn])||{}).name||''):''}${g.access?' · '+esc(g.access):''}${g.zone?' · zone '+esc(g.zone):''}</span>${done?`<div class="meta">Checked in ${fmtTs(done.at)} by ${esc(user(done.by).name)}</div>`:''}</div>${done?'<span class="pill ok">in</span>':`<button class="btn sm pri" data-act="guest-checkin" data-id="${g.id}" data-v="${esc(fn)}">Check in</button>`}</div></div>`}).join('')}</div>`:q?'<div class="muted small">No match on the confirmed list.</div>':''}<div class="row" style="gap:12px;margin-top:8px;align-items:flex-start">${gs.slice(0,1).map(g=>`<div class="badge"><div class="eyebrow">${esc(e.name)}</div><div class="nm">${esc(g.name)}</div><div class="small muted">${esc(fn)}${g.table&&g.table[fn]?' · '+esc((S.tables.find(t=>t.id===g.table[fn])||{}).name||''):''}${g.zone?' · '+esc(g.zone):''}</div>${qrSvg(g.id+fn)}<div class="meta">sample badge</div></div>`).join('')}</div></div>`}
ACTS_CHANGE['ci-fn']=el=>{S.ui.ciFn=el.value;saveUI();render()};ACTS_INPUT['ciq']=el=>{S.ui.ciq=el.value;saveUI();const pos=el.selectionStart;render();const n=F('ciq');if(n){n.focus();try{n.setSelectionRange(pos,pos)}catch(e){}}};
act('guest-checkin',({id,v})=>{const g=S.guests.find(x=>x.id===id);g.checkedIn=g.checkedIn||{};if(g.checkedIn[v])return toast('Already checked in');g.checkedIn[v]={at:nowISO(),by:UI.userId};touch(g);save();render();toast(g.name+' checked in')});
act('zones-edit',({E})=>{const e=E();openModal(`${hd('Access zones')}<form id="f-zn"><label for="znz">Zones (comma separated)</label><input id="znz" value="${esc((e.accessZones||['Main']).join(', '))}"><div class="help">Assign a zone on the guest (VIP, Backstage). Badges print the zone; the desk checks it.</div>${ft('Save')}</form>`);F('f-zn').addEventListener('submit',x=>{x.preventDefault();e.accessZones=F('znz').value.split(',').map(s=>s.trim()).filter(Boolean);touch(e);save();closeModal();render()})});
act('badges-print',({E,v})=>{const e=E();const gs=guestsOf(e.id).filter(g=>((g.rsvp||{}).perFunction||{})[v]==='yes');downloadBlob('badges-'+v+'.pdf',makePdf(`Badges — ${e.name} — ${v}`,gs.map(g=>({t:`${g.name}  |  ${g.table&&g.table[v]?(S.tables.find(t=>t.id===g.table[v])||{}).name||'':''}  |  ${g.zone||'Main'}  |  id ${g.id.slice(0,6)}`}))))});
/* ---------- Family collaboration ---------- */
function familyCard(e){const fc=e.familyContacts||[];return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Family collaboration</h3><div class="small muted">Named people with named rights. Only the decision-maker on the client record can approve spend; others may see approved details or help with the guest list — explicitly, never because they share a link.</div></div>${can('events.edit')&&!locked(e)?`<button class="btn sm" data-act="family-add">+ Family contact</button>`:''}</div><div class="list" style="margin-top:6px">${fc.map(f=>`<div class="item" style="padding:5px 0"><div class="row between"><div class="small"><b>${esc(f.name)}</b> · ${esc(f.role)} · ${esc(f.phone||'')}<div class="meta">${f.rights.approve?'<span class="pill ok">may approve spend</span>':'<span class="pill grey">no spend approval</span>'} ${f.rights.guestList?'<span class="pill ok">guest list</span>':''} ${f.rights.view?'<span class="pill ok">view approved details</span>':''}</div></div><div class="row" style="gap:4px"><a class="btn sm" href="#family/${f.token}" style="text-decoration:none">Open their page</a><button class="btn sm" data-act="family-del" data-id="${f.id}">Remove</button></div></div></div>`).join('')||'<div class="muted small">None. The client contact remains the only decision-maker.</div>'}</div></div>`}
act('family-add',({E})=>{const e=E();openModal(`${hd('Family contact')}<form id="f-fc"><label for="fcn">Name</label><input id="fcn" required><div class="two"><div><label for="fcr">Role</label><input id="fcr" placeholder="Bride's uncle"></div><div><label for="fcp">Phone</label><input id="fcp" inputmode="tel"></div></div><label class="chk"><input type="checkbox" id="fca"> May approve spend and changes (adds them as a named decision-maker)</label><label class="chk"><input type="checkbox" id="fcg" checked> May edit the guest list and RSVPs</label><label class="chk"><input type="checkbox" id="fcv" checked> May view approved schedule and guest-facing details</label>${ft('Add')}</form>`);F('f-fc').addEventListener('submit',x=>{x.preventDefault();e.familyContacts=(e.familyContacts||[]).concat([{id:uid(),name:F('fcn').value.trim(),role:F('fcr').value.trim(),phone:F('fcp').value.trim(),rights:{approve:F('fca').checked,guestList:F('fcg').checked,view:F('fcv').checked},token:Math.random().toString(36).slice(2,10),addedBy:UI.userId,addedAt:nowISO()}]);touch(e);audit('update','events',e.id,'family contact added',e.id);save();closeModal();render()})});
act('family-del',({E,id})=>{const e=E();e.familyContacts=(e.familyContacts||[]).filter(f=>f.id!==id);touch(e);save();render()});
function vFamily(){const tok=S.ui.familyToken||'';let e=null,f=null;S.events.forEach(x=>(x.familyContacts||[]).forEach(c=>{if(c.token===tok){e=x;f=c}}));const back=`<a href="#events" class="btn sm" style="text-decoration:none;margin-top:10px;display:inline-block">← Back to the app</a>`;if(!f)return `<div class="login"><div class="card" style="max-width:520px;margin:30px auto"><h2>Link not found</h2>${back}</div></div>`;const rc=rsvpCounts(e);const reqs=live(S.clientReqs).filter(r=>r.eventId===e.id&&r.status==='sent');return `<div class="login"><div class="card" style="max-width:640px;margin:30px auto"><div class="eyebrow">${esc(e.client)} · family page</div><h1 style="font-size:22px">${esc(e.name)}</h1><div class="small muted">Hello ${esc(f.name)} (${esc(f.role)}). You can: ${f.rights.view?'see the schedule':''}${f.rights.guestList?' · update the guest list':''}${f.rights.approve?' · approve decisions':''}. You cannot see prices, vendors\' amounts or anything internal.</div>${f.rights.view?`<h3 style="margin-top:12px">Schedule</h3><div class="list">${fnNames(e).map(fn=>{const d=fnOf(e,fn);return `<div class="item" style="padding:5px 0"><b>${esc(fn)}</b> · ${fmtDate(d.date)}${d.start?' · '+d.start:''} · ${esc(d.venue||'')}</div>`}).join('')}</div>`:''}${f.rights.guestList?`<h3 style="margin-top:12px">Guest list</h3><div class="small">${Object.entries(rc).map(([fn,r])=>`${esc(fn)}: ${r.yes} yes · ${r.pending} pending`).join(' · ')}</div><div class="meta">Full editing happens through the RSVP links per household; ask ${esc(user(e.plannerId).name)} to add households.</div>`:''}${f.rights.approve&&reqs.length?`<h3 style="margin-top:12px">Decisions waiting</h3><div class="list">${reqs.map(r=>`<div class="item" style="padding:5px 0">${esc(r.kind)}: ${esc(r.desc)} · <a href="#client/${r.token}">decide</a></div>`).join('')}</div>`:f.rights.approve?'<div class="muted small" style="margin-top:8px">No decisions waiting.</div>':''}<div class="meta" style="margin-top:10px">${sb('authenticated family access')}</div>${back}</div></div>`}
/* ---------- Guest information page ---------- */
function websiteCard(e){const w=e.guestInfo||{};return `<div class="card" style="margin-top:12px"><div class="row between"><div><h3>Guest information page</h3><div class="small muted">Directions, schedule, dress code and approved notes on one public page; or link an existing wedding website instead of building one.</div></div>${can('events.edit')&&!locked(e)?`<button class="btn sm" data-act="guestinfo-edit">Edit</button>`:''}</div><div class="small" style="margin-top:6px">${w.enabled?`<a href="#guestinfo/${guestInfoToken(e)}">Open the page</a> · <span class="meta">unguessable link; Edit → unpublish to withdraw</span> · ${w.externalUrl?'links to '+esc(w.externalUrl):'built here'}`:'Not published.'}</div></div>`}
act('guestinfo-edit',({E})=>{const e=E();const w=e.guestInfo||{enabled:false,directions:'',dress:'',notes:'',externalUrl:''};openModal(`${hd('Guest information page')}<form id="f-gi"><label class="chk"><input type="checkbox" id="gie" ${w.enabled?'checked':''}> Publish</label><label for="giu">Existing website URL (if the family already has one — the page just links to it)</label><input id="giu" value="${esc(w.externalUrl||'')}"><label for="gid">Directions & parking</label><textarea id="gid">${esc(w.directions||'')}</textarea><label for="gir">Dress code</label><input id="gir" value="${esc(w.dress||'')}"><label for="gin">Approved notes (gifts, children, photography)</label><textarea id="gin">${esc(w.notes||'')}</textarea>${ft('Save')}</form>`);F('f-gi').addEventListener('submit',x=>{x.preventDefault();e.guestInfo={enabled:F('gie').checked,externalUrl:F('giu').value.trim(),directions:F('gid').value.trim(),dress:F('gir').value.trim(),notes:F('gin').value.trim()};touch(e);save();closeModal();render()})});
function vGuestInfo(){const e=eventByToken('guestInfoToken',S.ui.guestinfoToken||'');const back=`<a href="#events" class="btn sm" style="text-decoration:none;margin-top:10px;display:inline-block">← Back to the app</a>`;if(!e||!(e.guestInfo||{}).enabled)return `<div class="login"><div class="card" style="max-width:520px;margin:30px auto"><h2>Not published</h2>${back}</div></div>`;const w=e.guestInfo;return `<div class="login"><div class="card" style="max-width:640px;margin:30px auto"><div class="eyebrow">${esc(e.client)}</div><h1 style="font-size:24px">${esc(e.name)}</h1>${w.externalUrl?`<p><a href="${esc(w.externalUrl)}" target="_blank" rel="noopener">Our website →</a></p>`:''}<h3 style="margin-top:12px">Schedule</h3><div class="list">${fnNames(e).map(fn=>{const d=fnOf(e,fn);return `<div class="item" style="padding:5px 0"><b>${esc(fn)}</b> · ${fmtDate(d.date)}${d.start?' · '+d.start:''} · ${esc(d.venue||e.venue||'')}</div>`}).join('')}</div>${w.directions?`<h3 style="margin-top:12px">Getting there</h3><div class="small">${esc(w.directions)}</div>`:''}${w.dress?`<h3 style="margin-top:12px">Dress code</h3><div class="small">${esc(w.dress)}</div>`:''}${w.notes?`<h3 style="margin-top:12px">Notes</h3><div class="small">${esc(w.notes)}</div>`:''}<div class="meta" style="margin-top:12px">Managed by ${esc(S.company.name)}. No personal data of guests appears here.</div>${back}</div></div>`}
/* gates & attention */
GATE_EXT.push((e,next,g)=>{if(next==='eventweek'&&modOn('guests')&&guestsOf(e.id).length){fnNames(e).forEach(fn=>{if(!(e.cateringCount||{})[fn])g.push(`Final catering count for ${fn} not approved`)})}});
ATT_EXT.push(att=>{if(!can('events.edit')||!modOn('guests'))return;S.events.filter(isLive).forEach(e=>{if(!guestsOf(e.id).length)return;const rc=rsvpCounts(e);fnNames(e).forEach(fn=>{const cc=(e.cateringCount||{})[fn];if(cc&&rc[fn].yes>cc.count)att.push({kind:'warn',tag:'RSVPs above catering count',e,txt:`${fn}: ${rc[fn].yes} yes vs ${cc.count} approved`,tab:'guests'});if(!cc&&daysUntil(fnOf(e,fn).date)<=5&&daysUntil(fnOf(e,fn).date)>=0)att.push({kind:'bad',tag:'Catering count due',e,txt:`${fn} in ${daysUntil(fnOf(e,fn).date)} days: ${rc[fn].yes} yes, ${rc[fn].pending} pending`,tab:'guests'})})})});
